let QUIZZO_AVATAR_CATALOG = window.QUIZZO_AVATAR_CATALOG || {avatars:[],accessories:[]};
let AVATAR_COUNT = QUIZZO_AVATAR_CATALOG.avatars?.length || 1;
let ACCESSORY_COUNT = 0;
