const ACCESSORY_NAMES = [];
let AVATAR_NEW_BADGES = {};
function refreshAvatarCatalog(){
  QUIZZO_AVATAR_CATALOG = window.QUIZZO_AVATAR_CATALOG || QUIZZO_AVATAR_CATALOG || {avatars:[],accessories:[]};
  AVATAR_COUNT = Math.max(1, QUIZZO_AVATAR_CATALOG.avatars?.length || 0);
  ACCESSORY_COUNT = 0;
  AVATAR_NAMES = (QUIZZO_AVATAR_CATALOG.avatars||[]).map(x=>x?.name||"Avatar");
}
async function ensureAvatarCatalog(){
  if(window.QUIZZO_AVATAR_CATALOG?.avatars?.length){ refreshAvatarCatalog(); return true; }
  const deadline=Date.now()+2500;
  while(Date.now()<deadline){
    if(window.QUIZZO_AVATAR_CATALOG?.avatars?.length){ refreshAvatarCatalog(); return true; }
    await new Promise(r=>setTimeout(r,50));
  }
  try{
    const existing=document.querySelector('script[src*="avatars.js"]');
    if(!existing){
      await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=new URL('./avatars.js?v=81',import.meta.url).href;s.defer=true;s.onload=resolve;s.onerror=reject;document.head.appendChild(s)})
    } else await new Promise(r=>setTimeout(r,250));
  }catch(e){console.warn('Quizzo avatars.js kon niet worden geladen',e)}
  refreshAvatarCatalog();
  return !!window.QUIZZO_AVATAR_CATALOG?.avatars?.length;
}
const DEFAULT_PROFILE={avatar:0,accessory:null};
const clampIndex=(v,max)=>{const n=Number(v);return Number.isInteger(n)&&n>=0&&n<max?n:0};
const normalizeProfile=p=>({avatar:clampIndex(p?.avatar,AVATAR_COUNT),accessory:null});
const randProfile=()=>({avatar:Math.floor(Math.random()*AVATAR_COUNT),accessory:null});
function avatarSrc(i){return QUIZZO_AVATAR_CATALOG.avatars?.[clampIndex(i,AVATAR_COUNT)]?.src||"";}
function avatarBadge(i){const n=SITE_CFG?.avatars?.[i]?.new===true;return n?'<span class="avatar-choice-new">Nieuw</span>':''}
function avatarReaction(emotion){const map={happy:['✨','Goed!'],celebrate:['🎉','Winnaar!'],sad:['💧','Oei!'],rankup:['⬆️','Omhoog!'],overtaken:['😵','Ingehaald!']};const v=map[emotion];return v?`<span class="avatar-reaction reaction-${emotion}" aria-hidden="true"><b>${v[0]}</b><small>${v[1]}</small></span>`:""}

// All 25 avatar source files use a 512x512 transparent canvas, but their visible artwork
// has different transparent margins. A plain object-fit:contain therefore makes some
// characters look too high, too low, too large or too small. These source-space alpha
// bounds normalize the visible character to one consistent frame in every UI location.
const AVATAR_BBOXES=[
  [128,32,467,467],[101,46,471,468],[146,32,462,464],[147,32,459,467],[70,72,471,470],
  [150,32,459,464],[122,32,465,467],[102,43,471,468],[73,89,471,467],[150,32,469,465],
  [82,66,471,469],[112,33,471,467],[173,32,453,467],[156,32,456,467],[58,32,453,502],
  [148,34,471,471],[112,36,471,461],[41,75,471,502],[83,55,471,463],[137,32,465,457],
  [130,24,381,494],[106,24,405,494],[149,25,362,494],[158,24,368,494],[133,25,379,493]
];
function avatarLayout(index,size){
  const S=Math.max(28,Number(size)||48);
  const b=AVATAR_BBOXES[clampIndex(index,AVATAR_BBOXES.length)]||[0,0,512,512];
  const bw=Math.max(1,b[2]-b[0]), bh=Math.max(1,b[3]-b[1]);
  // Keep the visible artwork inside a consistent visual box: ~82% wide and ~90% high.
  const scale=Math.min((S*0.82)/bw,(S*0.90)/bh);
  const render=S===0?512:512*scale;
  const visualW=bw*scale, visualH=bh*scale;
  const left=(S-visualW)/2-b[0]*scale;
  const bottom=S*0.94;
  const top=bottom-visualH-b[1]*scale+(b[3]-b[1])*scale;
  // Equivalent to aligning the artwork's visible bottom at 94% of the frame.
  const top2=S*0.94-b[3]*scale;
  return {S,render,left,top:top2};
}
function avatarMarkup(p,size=48,emotion=""){
  const v=normalizeProfile(p),src=avatarSrc(v.avatar),L=avatarLayout(v.avatar,size);
  const st=`--avatar-size:${L.S}px;--avatar-img-size:${L.render}px;--avatar-img-left:${L.left}px;--avatar-img-top:${L.top}px`;
  // Multiplayer host-schermen tonen alleen het avatar zelf. Reactie-badges zoals “Goed!”
  // zijn alleen voor het spelersscherm bedoeld. In solo is dezelfde speler tegelijk host+player,
  // dus daar blijven reacties zichtbaar.
  const showReaction=!!emotion&&(!HOST||G?.mode==="solo");
  return `<span class="avatar-inline ${emotion?`mood-${emotion}`:""}" style="${st}"><img class="avatar-svg-img" src="${src}" alt="" draggable="false" decoding="async">${showReaction?avatarReaction(emotion):""}</span>`;
}
function savedProfile(){try{return normalizeProfile(JSON.parse(localStorage.getItem("quizzo_avatar")||"null"))}catch(_){return {...DEFAULT_PROFILE}}}
function saveProfile(p){localStorage.setItem("quizzo_avatar",JSON.stringify(normalizeProfile(p)))}
let avatarPickerCallback=null,avatarDraft={...DEFAULT_PROFILE},avatarPickerSearch="";
function avatarChoiceMarkup(){
  const items=[];
  for(let i=0;i<AVATAR_COUNT;i++){
    const a=QUIZZO_AVATAR_CATALOG.avatars[i]||{};
    if(!ADM && SITE_CFG?.avatars?.[i]?.online!==true)continue;
    if(avatarPickerSearch&&!String(a.name||"").toLowerCase().includes(avatarPickerSearch.toLowerCase()))continue;
    const badge=avatarBadge(i);
    items.push(`<button class="avatar-option ${i===avatarDraft.avatar?'selected':''}" data-a="pickAvatar" data-index="${i}" aria-label="${esc(a.name||`Avatar ${i+1}`)}"><span class="avatar-option-art avatar-character-preview">${avatarMarkup({avatar:i},112)}${badge}</span><strong>${esc(a.name||`Avatar ${i+1}`)}</strong><small>${a.kind==='human'?'Menselijk':a.kind==='snowman'?'Sneeuwpop':a.kind==='skeleton'?'Skelet':'Dier'}</small></button>`);
  }
  return items.join("");
}
function openAvatarPicker(initial,done,title="Kies je avatar"){
  avatarDraft=normalizeProfile(initial);avatarPickerCallback=done;avatarPickerSearch="";
  document.querySelector('.avatar-modal')?.remove();
  const m=document.createElement('div');m.className='avatar-modal avatar-modal-full';
  const currentBadge=avatarBadge(avatarDraft.avatar);
  m.innerHTML=`<div class="avatar-picker-screen">
    <header class="avatar-picker-top"><div class="avatar-top-brand"><span class="avatar-top-icon">🐾</span><div><span class="eyebrow">QUIZZO</span><h1>${esc(title)}</h1><p>Kies één van de 25 personages.</p></div></div><div class="avatar-top-actions"><span class="avatar-phone-badge">📱 Telefoon ondersteund</span><button class="avatar-close-btn" data-a="closeAvatarPicker" aria-label="Sluiten">×</button></div></header>
    <main class="avatar-picker-main"><section class="avatar-showcase-panel"><div class="showcase-label">JOUW PERSONAGE</div><div class="showcase-stage" id="avatarLive"><div class="showcase-badge" id="avatarLiveBadge">${currentBadge}</div>${avatarMarkup(avatarDraft,275)}</div><div class="showcase-name"><strong id="avatarLiveName">${esc(AVATAR_NAMES[avatarDraft.avatar]||'Avatar')}</strong><span>Dierlijk of speciaal personage</span></div><div class="showcase-tip">Je personage wordt gebruikt in de lobby, naast je naam, op het leaderboard en op het podium.</div></section>
      <section class="avatar-catalog-panel"><div class="catalog-toolbar"><div class="avatar-tabs"><button class="avatar-tab active">🐾 Personages <b>${AVATAR_COUNT}</b></button></div><label class="avatar-search">⌕<input id="avatarSearch" placeholder="Zoek op naam..." value="${esc(avatarPickerSearch)}"></label></div><div class="catalog-scroll"><div class="catalog-heading"><div><span class="eyebrow">PERSONAGES</span><h2>Kies je personage</h2></div><span class="catalog-count">${AVATAR_COUNT} beschikbaar</span></div><div class="avatar-catalog-grid show-avatars">${avatarChoiceMarkup()}</div></div></section></main>
    <footer class="avatar-picker-bottom"><div class="selection-status"><span>GESELECTEERD</span><strong id="avatarSelectedName">${esc(AVATAR_NAMES[avatarDraft.avatar]||'Avatar')}</strong></div><div class="avatar-bottom-actions"><button class="btn w" data-a="closeAvatarPicker">Annuleren</button><button class="btn g avatar-ready" data-a="avatarDone">✓ Klaar</button></div></footer>
  </div>`;
  document.body.append(m);document.body.classList.add('avatar-picker-open');setTimeout(()=>m.querySelector('#avatarSearch')?.focus(),0);
}
function rerenderAvatarPicker(){
  const m=document.querySelector('.avatar-picker-screen');if(!m)return;
  const live=m.querySelector('#avatarLive');if(live){live.innerHTML=`<div class="showcase-badge" id="avatarLiveBadge">${avatarBadge(avatarDraft.avatar)}</div>${avatarMarkup(avatarDraft,275)}`}
  const label=m.querySelector('#avatarLiveName');if(label)label.textContent=AVATAR_NAMES[avatarDraft.avatar]||'Avatar';
  const selected=m.querySelector('#avatarSelectedName');if(selected)selected.textContent=AVATAR_NAMES[avatarDraft.avatar]||'Avatar';
  const grid=m.querySelector('.avatar-catalog-grid');if(grid)grid.innerHTML=avatarChoiceMarkup();
}
act.pickAvatar=d=>{avatarDraft.avatar=clampIndex(d.index,AVATAR_COUNT);rerenderAvatarPicker()};
act.avatarDone=()=>{const p=normalizeProfile(avatarDraft);saveProfile(p);const cb=avatarPickerCallback;avatarPickerCallback=null;document.querySelector('.avatar-modal')?.remove();document.body.classList.remove('avatar-picker-open');cb?.(p)};
act.closeAvatarPicker=()=>{avatarPickerCallback=null;document.querySelector('.avatar-modal')?.remove();document.body.classList.remove('avatar-picker-open')};
act.customizeAvatar=()=>{if(!G||!CODE)return;const cur=G.players?.[user.uid]||savedProfile();openAvatarPicker(cur,p=>{update(ref(db,`games/${CODE}/players/${user.uid}`),p).then(()=>toast('Avatar bijgewerkt!'),e=>toast(em(e)) )},'Avatar aanpassen')};
document.addEventListener('input',e=>{if(e.target?.id!=='avatarSearch')return;avatarPickerSearch=e.target.value||'';const grid=document.querySelector('.avatar-catalog-grid');if(grid)grid.innerHTML=avatarChoiceMarkup()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('.avatar-modal'))act.closeAvatarPicker()});

/* Badges: the site owner can mark each avatar individually as "Nieuw". */
try{onValue(ref(db,'avatarBadges'),snap=>{AVATAR_NEW_BADGES=snap.val()||{};const modal=document.querySelector('.avatar-modal');if(modal)rerenderAvatarPicker()})}catch(_){AVATAR_NEW_BADGES={}}

/* ---------- Accounts (opgeslagen in de Realtime Database, zonder Firebase Authentication) ---------- */
const enc=new TextEncoder(),hex=b=>[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,"0")).join("");
async function hashPw(pw,salt){const k=await crypto.subtle.importKey("raw",enc.encode(pw),"PBKDF2",false,["deriveBits"]);
 return hex(await crypto.subtle.deriveBits({name:"PBKDF2",hash:"SHA-256",salt:enc.encode(salt),iterations:100000},k,256))}
const mailKey=e=>e.toLowerCase().replace(/\./g,",");
const userKey=n=>encodeURIComponent(n.toLowerCase()).replace(/\./g,"%2E");
async function login(key,name,email){
 user={uid:key,displayName:name,email};
 // Het normale Quizzo-account blijft ingelogd na refresh/rejoin.
 // Sitebeheer blijft bewust apart en wordt nooit opgeslagen.
 localStorage.setItem("quizzo_user",JSON.stringify(user));
 ADM=null;
 home();
}
try{
 const savedUser=JSON.parse(localStorage.getItem("quizzo_user")||"null");
 if(savedUser && savedUser.uid && (savedUser.displayName || savedUser.email)){
  user={uid:String(savedUser.uid),displayName:String(savedUser.displayName||savedUser.email||""),email:String(savedUser.email||"")};
 }
}catch(_){
 localStorage.removeItem("quizzo_user");
 user=null;
}
setTimeout(home,0);
function authView(){
 const reg=mode=="reg";
 A.innerHTML=`<div class="center"><h1 class="logo">Quizzo!</h1><form id="af" class="card"><h2>${reg?"Account maken":"Inloggen"}</h2>
 ${reg?'<input name="u" placeholder="Gebruikersnaam" required minlength="2" maxlength="30">':""}
 <input name="e" type="${reg?"email":"text"}" placeholder="${reg?"E-mailadres":"Gebruikersnaam of e-mailadres"}" required>
 <input name="p" type="password" placeholder="Wachtwoord (minimaal 6 tekens)" required minlength="6">
 <button class="btn b">${reg?"Registreren":"Inloggen"}</button>
 <a class="link" data-a="mode">${reg?"Heb je al een account? Inloggen":"Nog geen account? Registreren"}</a></form></div>`;
 $("#af").onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.target),id=f.get("e").trim(),pw=f.get("p"),btn=ev.target.querySelector("button");btn.disabled=true;
  try{
   if(reg){const name=f.get("u").trim(),key=userKey(name);
    if(name.length<2)throw "Gebruikersnaam: minimaal 2 tekens.";
    if((await get(ref(db,"users/"+key))).exists())throw "Deze gebruikersnaam is al bezet.";
    if((await get(ref(db,"emails/"+mailKey(id)))).exists())throw "Dit e-mailadres is al in gebruik.";
    const salt=hex(crypto.getRandomValues(new Uint8Array(16)));
    await set(ref(db,"users/"+key),{username:name,email:id,salt,hash:await hashPw(pw,salt),created:Date.now()});
    await set(ref(db,"emails/"+mailKey(id)),key);
    login(key,name,id)}
   else{let key=userKey(id),u=(await get(ref(db,"users/"+key))).val();
    if(!u&&id.includes("@")){key=(await get(ref(db,"emails/"+mailKey(id)))).val()||"";u=key?(await get(ref(db,"users/"+key))).val():null}
    if(!u||u.hash!==await hashPw(pw,u.salt))throw "Gebruikersnaam of wachtwoord klopt niet.";
    login(key,u.username,u.email)}
  }catch(err){toast(typeof err=="string"?err:em(err));btn.disabled=false}}}
act.mode=()=>{mode=mode=="reg"?"login":"reg";authView()};
act.out=()=>{localStorage.removeItem("quizzo_user");user=null;tab="join";home()};

/* ---------- Home ---------- */
function home(){
 cleanup();Q=null;joinCode=null;if(!user)return authView();
 A.innerHTML=`<header><b class="logo s">Quizzo!</b><span class="hr"><button class="btn w sm ib" data-a="log" title="Updatelog" aria-label="Updatelog">📢</button><button class="btn w sm" data-a="admin" title="Sitebeheer">⚙ ${ADM?"Sitebeheer actief":"Sitebeheer"}</button><button class="btn w sm" data-a="menu">${esc(user.displayName||user.email)} ▾</button></span></header>
 <nav class="tabs">${[["join","Quiz joinen"],["discover","Ontdek quizzen"],["make","Quiz maken"],["mine","Gemaakte quizzen"],...(ADM?[["admin","Sitebeheer"]]:[])].map(([k,l])=>`<button data-a="tab" data-k="${k}" class="${tab==k?"on":""}">${l}</button>`).join("")}</nav><main id="tc" class="wrap"></main>`;
 tabView()}
act.tab=d=>{tab=d.k;joinCode=null;home()};
async function tabView(){
 const c=$("#tc");
 if(tab=="admin"){
  if(!ADM){tab="join";return tabView()}
  adminOverlay();
  renderAdminTabs();
  return renderAdminDashboard();
 }
 if(tab=="join"){
  c.innerHTML=joinCode?`<div class="card narrow"><h2>Kies je naam</h2><input id="nm" maxlength="20" placeholder="Jouw naam" value="${esc(user.displayName||"")}"><button class="btn g" data-a="enter">Meedoen</button></div>`
  :`<div class="card narrow"><h2>Quiz joinen</h2><input id="code" inputmode="numeric" maxlength="6" placeholder="Spelcode"><button class="btn b" data-a="check">Verder</button></div>`;
  return;
 }
 if(tab=="discover"){
  await loadSiteConfig();
  c.innerHTML=`<div class="discover-head"><div><span class="eyebrow">OPENBAAR</span><h2>Ontdek quizzen</h2><p>Bekijk, lees en speel alle openbare quizzen. Klik op een quiz om de vragen en antwoorden te bekijken. Je kunt openbare quizzen alleen spelen, nooit bewerken.</p></div><div class="discover-badge">🌍 Iedereen kan spelen</div></div><div id="publicQuizList" class="discover-grid"><div class="card narrow loading-card">Quizzen laden...</div></div>`;
  const qsSnap=await get(ref(db,"quizzes")).catch(e=>(toast(em(e)),null));
  const all=qsSnap?.val()||{};
  const items=[];
  const ownerIds=new Set();
  Object.entries(all).forEach(([ownerId,ownerQuizzes])=>{
    if(!ownerQuizzes || typeof ownerQuizzes!=="object")return;
    Object.entries(ownerQuizzes).forEach(([id,qz])=>{
      // Oude quizzen hebben soms nog geen public-veld: die behandelen we als openbaar.
      if(!qz||typeof qz!=="object"||qz.public===false||!quizAllowed(ownerId,id))return;
      const count=arr(qz.questions).length;
      if(!String(qz.title||"").trim()||!count)return;
      ownerIds.add(ownerId);
      const mine=ownerId===user.uid;
      items.push({id,ownerId,mine,qz:{...qz,public:true},ownerName:qz.creatorName||"Quizzo speler"});
    });
  });
  const ownerNames={};
  await Promise.all([...ownerIds].map(async ownerId=>{
    try{
      const snap=await get(ref(db,"users/"+ownerId));
      ownerNames[ownerId]=snap.val()?.username||"Quizzo speler";
    }catch(e){
      ownerNames[ownerId]="Quizzo speler";
    }
  }));
  items.forEach(item=>{if(!item.qz.creatorName)item.ownerName=ownerNames[item.ownerId]||item.ownerName});
  items.sort((a,b)=>(Number(b.qz.updated)||0)-(Number(a.qz.updated)||0));
  const list=$("#publicQuizList");
  if(!list)return;
  list.innerHTML=items.length?items.map((item,i)=>`<article class="public-qcard" role="button" tabindex="0" data-a="publicView" data-owner="${esc(item.ownerId)}" data-id="${esc(item.id)}" style="--delay:${Math.min(i,12)*35}ms">
    <div class="public-thumb" style="background-image:url('${esc(themeAsset(safeTheme(item.qz.theme),"jpg"))}')"><span>${THEMES[safeTheme(item.qz.theme)].icon} ${esc(THEMES[safeTheme(item.qz.theme)].name)}</span><div class="public-thumb-overlay">👀 Bekijk quiz</div></div>
    <div class="public-qbody"><div class="public-meta"><span>👤 ${esc(item.ownerName)}${item.mine?" · Jouw quiz":""}</span><span>📝 ${countLabel(item.qz.questions)}</span></div><h3>${esc(item.qz.title)}</h3><p class="public-description">${esc(item.qz.description||"Geen beschrijving toegevoegd.")}</p><small class="public-open-note">${item.mine?"Openbare quiz · bekijken en spelen · niet bewerkbaar":"Openbare quiz · klik om vragen en antwoorden te bekijken"}</small>${gameOnline("solo")||gameOnline("multiplayer")?`<button class="btn b" data-a="publicPlay" data-owner="${esc(item.ownerId)}" data-id="${esc(item.id)}">▶ Spelen</button>`:""}</div>
  </article>`).join(""):`<div class="card narrow empty-discover"><h2>Nog geen openbare quizzen</h2><p>Wanneer publieke quizzen zijn opgeslagen, verschijnen ze hier automatisch.</p><button class="btn w sm" data-a="tab" data-k="mine">Naar mijn quizzen</button></div>`;
  wireThemePreviews();
  return;
 }
 if(tab=="make"){
  c.innerHTML=`<div class="card narrow"><h2>Quiz maken</h2><input id="qn" maxlength="60" placeholder="Naam van de quiz"><button class="btn b" data-a="create">Maken</button></div>`;
  return;
 }
 c.innerHTML="Laden...";
 const s=await get(ref(db,"quizzes/"+user.uid)).catch(e=>(toast(em(e)),null)),v=s?.val()||{},ids=Object.keys(v);
 c.innerHTML=ids.length?ids.map(id=>`<div class="qcard"><div><b>${esc(v[id].title)}</b><small>${arr(v[id].questions).length} ${arr(v[id].questions).length===1?"onderdeel":"onderdelen"} · ${v[id].public===false?"privé":"openbaar"}</small></div><div>
   <button class="btn b sm" data-a="play" data-id="${id}">Spelen</button> <button class="btn g sm" data-a="host" data-id="${id}">Hosten</button> <button class="btn w sm" data-a="edit" data-id="${id}">Bewerken</button> <button class="btn r sm" data-a="delq" data-id="${id}">Verwijderen</button></div></div>`).join("")
  :`<div class="card narrow">Je hebt nog geen quizzen. Ga naar "Quiz maken" om te beginnen.</div>`;
}
const countLabel=questions=>{const n=arr(questions).length;return `${n} ${n===1?"onderdeel":"onderdelen"}`};
act.check=async()=>{const c=$("#code").value.trim();if(!c)return;
 const s=await get(ref(db,"games/"+c)).catch(e=>(toast(em(e)),null));if(!s)return;
 if(!s.exists()||s.val().state!="lobby")return toast("Deze code klopt niet of de quiz is al gestart.");
 joinCode=c;tabView()};
act.enter=async()=>{const n=$("#nm").value.trim();if(!n)return toast("Vul een naam in.");
 const s=await get(ref(db,"games/"+joinCode)).catch(()=>null);if(!s?.exists()||s.val().state!="lobby")return toast("Deze quiz is niet meer beschikbaar."),home();
 const profile=randProfile();saveProfile(profile);await set(ref(db,`games/${joinCode}/players/${user.uid}`),{name:n,score:0,...profile}).catch(e=>toast(em(e)));run(joinCode,false)};
act.create=()=>{const n=$("#qn").value.trim();if(!n)return toast("Geef je quiz eerst een naam.");
 Q={title:n,description:"",theme:"classic",public:true,questions:[]};QID=null;ADMIN_EDIT=null;SEL=-1;editorView()};
act.edit=async d=>{const v=(await get(ref(db,`quizzes/${user.uid}/${d.id}`))).val();
 Q={title:v.title||"",description:v.description||"",theme:safeTheme(v.theme),public:v.public!==false,creatorName:v.creatorName||user.displayName||"Quizzo speler",questions:arr(v.questions).map(normalizeQuestion)};QID=d.id;ADMIN_EDIT=null;SEL=0;editorView()};
act.delq=async d=>{if(confirm("Deze quiz verwijderen?")){await remove(ref(db,`quizzes/${user.uid}/${d.id}`));tabView()}};

async function openPlayChooser(qz,ownerId,id){
 if(!qz)return toast("Deze quiz kon niet worden geladen.");
 await loadSiteConfig();
 document.querySelectorAll(".modal").forEach(x=>x.remove());
 const m=document.createElement("div");m.className="modal";
 const card=document.createElement("div");
 card.className="card mode-card";
 const badge=document.createElement("div"); badge.className="public-mode-badge"; badge.textContent="🌍 Openbare quiz";
 const title=document.createElement("h2"); title.textContent=qz.title||"Openbare quiz";
 const info=document.createElement("p"); info.textContent="Kies hoe je deze quiz wilt spelen. De quiz blijft alleen-lezen voor jou.";
 let options=[];
 if(gameOnline("solo")){const solo=document.createElement("button");solo.className="btn b";solo.dataset.a="publicSolo";solo.dataset.owner=ownerId;solo.dataset.id=id;solo.textContent="👤 Alleen spelen";if(SITE_CFG.gameTypes?.solo?.new){const b=document.createElement("i");b.className="site-new-badge";b.textContent="Nieuw";solo.append(" ",b)}options.push(solo)}
 if(gameOnline("multiplayer")){const multi=document.createElement("button");multi.className="btn g";multi.dataset.a="publicHost";multi.dataset.owner=ownerId;multi.dataset.id=id;multi.textContent="🎮 Multiplayer hosten";if(SITE_CFG.gameTypes?.multiplayer?.new){const b=document.createElement("i");b.className="site-new-badge";b.textContent="Nieuw";multi.append(" ",b)}options.push(multi)}
 const close=document.createElement("button");close.className="btn w";close.dataset.a="closem";close.textContent="Annuleren";options.push(close);card.append(badge,title,info,...options);m.append(card);
 document.body.append(m);
}
function publicQuestionHtml(q,i){
 q=q&&typeof q==='object'?q:{};
 const n=i+1;
 const time=Number(q.time)||20;
 const doubleText=q.doublePoints?'2× ':'';
 if(q.type==='dia'){
  return '<article class="preview-q preview-dia"><div class="preview-q-top"><span class="preview-number">'+n+'</span><span class="preview-type dia">🖼️ DIA</span><span class="preview-time">'+time+'s</span></div><h3>'+esc(q.text||'Dia')+'</h3><p>'+esc(q.info||'')+'</p><div class="preview-no-points">Geen vraag • geen punten</div></article>';
 }
 if(q.type==='slider'){const si=sliderInfo(q);return '<article class="preview-q preview-slider"><div class="preview-q-top"><span class="preview-number">'+n+'</span><span class="preview-type typing">↔️ SCHUIFREGELAAR</span><span class="preview-time">'+time+'s</span></div><h3>'+esc(q.text||'Schuifvraag')+'</h3><p>'+esc(String(q.start||1))+' → '+esc(String(q.end||100))+'</p><div class="preview-points">Max. 1000 punten · vooral gebaseerd op hoe dicht je bij het juiste getal zit</div></article>';}
 if(q.type==='typing'){
  const good=arr(q.a).filter(x=>String(x??'').trim()).map((a,j)=>'<div class="preview-answer-row"><span>'+(j+1)+'</span>'+esc(a)+'</div>').join('');
  return '<article class="preview-q preview-typing"><div class="preview-q-top"><span class="preview-number">'+n+'</span><span class="preview-type typing">⌨️ TYPEN</span><span class="preview-time">'+time+'s</span></div><h3>'+esc(q.text||'Typvraag')+'</h3><div class="preview-answer-label">Goede antwoorden</div><div class="preview-answer-list">'+(good||'<div class="preview-empty">Geen antwoorden ingesteld</div>')+'</div><div class="preview-points">'+doubleText+'max. 1000 punten · aftrek op milliseconde</div></article>';
 }
 const answers=arr(q.a);
 const typeClass=q.type==='tf'?'tf':'quiz';
 const typeLabel=q.type==='tf'?'✓✕ WAAR / NIET WAAR':'▲ QUIZVRAAG';
 const answerHtml=answers.map((a,j)=>{
   const cls=['r','b','y','g'][j%4];
   const sym=['▲','◆','●','■'][j%4];
   const correct=j===Number(q.correct);
   return '<div class="preview-answer '+cls+(correct?' correct':'')+'"><span>'+sym+'</span><em>'+esc(a??'')+'</em>'+(correct?'<b>✓ Goed</b>':'')+'</div>';
 }).join('');
 return '<article class="preview-q"><div class="preview-q-top"><span class="preview-number">'+n+'</span><span class="preview-type '+typeClass+'">'+typeLabel+'</span><span class="preview-time">'+time+'s</span></div><h3>'+esc(q.text||'Vraag')+'</h3><div class="preview-answer-grid">'+answerHtml+'</div><div class="preview-points">'+doubleText+'max. 1000 punten · juiste antwoord gemarkeerd</div></article>';
}
async function openPublicQuiz(qz,ownerId,id){
 if(!qz)return toast("Deze quiz kon niet worden geladen.");
 const m=document.createElement("div");m.className="modal public-view-modal";
 const qs=arr(qz.questions);
 m.innerHTML=`<div class="card public-view-card"><div class="public-view-head"><div><span class="eyebrow">🌍 OPENBARE QUIZ</span><h2>${esc(qz.title||"Quiz")}</h2><p class="public-view-description">${esc(qz.description||"Geen beschrijving toegevoegd.")}</p><p>Gemaakt door <b>${esc(qz.creatorName||"Quizzo speler")}</b> · ${countLabel(qs)}</p></div><button class="btn w sm" data-a="closem">Sluiten</button></div><div class="public-view-theme"><span>${THEMES[safeTheme(qz.theme)].icon}</span><b>${esc(THEMES[safeTheme(qz.theme)].name)}</b><small>Vragen en antwoorden bekijken</small></div><div class="public-question-list">${qs.length?qs.map(publicQuestionHtml).join(""):`<div class="card narrow"><p>Deze quiz heeft nog geen onderdelen.</p></div>`}</div><div class="public-view-actions">${gameOnline("solo")||gameOnline("multiplayer")?`<button class="btn b" data-a="publicPlay" data-owner="${esc(ownerId)}" data-id="${esc(id)}">▶ Spelen</button>`:""}<button class="btn w" data-a="closem">Sluiten</button></div></div>`;
 document.body.append(m);
}
act.publicView=async d=>{try{const qz=(await get(ref(db,`quizzes/${d.owner}/${d.id}`))).val();if(!qz||qz.public===false||!quizAllowed(d.owner,d.id))return toast("Deze quiz is niet online beschikbaar.");await openPublicQuiz(qz,d.owner,d.id)}catch(e){toast(em(e))}};

act.publicPlay=async d=>{
 try{const qz=(await get(ref(db,`quizzes/${d.owner}/${d.id}`))).val();if(qz?.public===false||!quizAllowed(d.owner,d.id))return toast("Deze quiz is niet online beschikbaar.");await openPlayChooser(qz,d.owner,d.id)}catch(e){toast(em(e))}
};
act.publicSolo=async d=>{
 act.closem();
 try{const qz=(await get(ref(db,`quizzes/${d.owner}/${d.id}`))).val();if(!qz||qz.public===false||!quizAllowed(d.owner,d.id))return toast("Deze quiz is niet online beschikbaar.");if(!gameOnline("solo"))return toast("Alleen spelen staat momenteel offline.");if(arr(qz.questions).some(q=>!typeOnline(q.type)))return toast("Deze quiz gebruikt een vraagtype dat momenteel offline staat.");openAvatarPicker(savedProfile(),async profile=>{const code=await createGame(qz,"solo",profile);run(code,true)},"Kies je avatar")}catch(e){toast(em(e))}
};
act.publicHost=async d=>{
 act.closem();
 try{const qz=(await get(ref(db,`quizzes/${d.owner}/${d.id}`))).val();if(!qz||qz.public===false||!quizAllowed(d.owner,d.id))return toast("Deze quiz is niet online beschikbaar.");if(!gameOnline("multiplayer"))return toast("Multiplayer staat momenteel offline.");if(arr(qz.questions).some(q=>!typeOnline(q.type)))return toast("Deze quiz gebruikt een vraagtype dat momenteel offline staat.");const code=await createGame(qz,"multiplayer");run(code,true)}catch(e){toast(em(e))}
};
act.play=async d=>{
 const qz=(await get(ref(db,`quizzes/${user.uid}/${d.id}`))).val();if(!qz)return toast("Deze quiz kon niet worden geladen.");
 await openPlayChooser(qz,user.uid,d.id);
};

/* ---------- Editor ---------- */
const newQ=(type="quiz")=>type==="tf"?{type:"tf",text:"",time:20,points:1000,doublePoints:false,leaderboard:true,a:["Waar","Niet waar"],correct:-1}:type==="dia"?{type:"dia",text:"",info:"",time:10,points:1000,doublePoints:false,leaderboard:true,a:[],correct:-1}:type==="typing"?{type:"typing",text:"",time:20,points:1000,doublePoints:false,leaderboard:true,a:[""],correct:-1}:type==="slider"?{type:"slider",text:"",time:30,points:1000,doublePoints:false,leaderboard:true,a:[],start:1,end:100,correctValue:50,correctStep:-1}:{type:"quiz",text:"",time:20,points:1000,doublePoints:false,leaderboard:true,a:["","","",""],correct:-1};
const roundSliderDisplay=v=>{const n=Number(v);if(!Number.isFinite(n))return 0;return Math.round(n/10)*10};
const sliderInfo=q=>{const start=Number(q.start),end=Number(q.end);if(!Number.isFinite(start)||!Number.isFinite(end)||start<1||end<start)return {count:0,step:0,values:[]};const rawStep=(end-start)/99;const step=rawStep<=1?1:Math.max(1,Math.round(rawStep/10)*10);const count=Math.min(100,Math.max(2,Math.floor((end-start)/step)+1));const values=[];for(let i=0;i<count;i++){const raw=i===count-1?end:start+i*step;let v=roundSliderDisplay(raw);v=Math.max(start,Math.min(end,v));if(!values.length||v!==values[values.length-1])values.push(v)}if(values[values.length-1]!==end&&values.length<100)values.push(roundSliderDisplay(end));return {count:values.length,step,values};};
const sliderValue=(q,i)=>{const x=sliderInfo(q);return x.values[Math.max(0,Math.min(x.count-1,Number(i)||0))]};
const sliderCorrectIndex=q=>{const x=sliderInfo(q);if(!x.count)return -1;const target=Number.isFinite(Number(q.correctValue))?Number(q.correctValue):(Number.isInteger(q.correctStep)?sliderValue(q,q.correctStep):x.values[0]);let best=0,bestD=Infinity;x.values.forEach((v,i)=>{const d=Math.abs(v-target);if(d<bestD){bestD=d;best=i}});return best};
const sliderCorrectValue=q=>{const x=sliderInfo(q);const idx=sliderCorrectIndex(q);return idx>=0?x.values[idx]:0};
const normalizeQuestion=q=>{const base={...q,a:q.type==="dia"||q.type==="slider"?[]:arr(q.a),info:q.info||"",time:Number.isInteger(q.time)?q.time:20,points:1000,doublePoints:q.type==="dia"?false:!!q.doublePoints,leaderboard:q.leaderboard!==false};if(q.type!=="slider")return base;const start=Number.isFinite(Number(q.start))&&Number(q.start)>=1?Math.floor(Number(q.start)):1;const end=Number.isFinite(Number(q.end))&&Number(q.end)>=start?Math.floor(Number(q.end)):Math.max(start,100);const correct=Number.isFinite(Number(q.correctValue))?Number(q.correctValue):50;return {...base,start,end,correctValue:Math.max(start,Math.min(end,correct)),correctStep:Number.isInteger(q.correctStep)?q.correctStep:-1}};
const qOk=q=>q.type==="dia"?q.text.trim()&&q.info.trim()&&q.time>=5&&q.time<=120&&Number.isInteger(q.time):q.type==="typing"?q.text.trim()&&q.a.some(x=>x.trim())&&q.time>=5&&q.time<=120&&Number.isInteger(q.time):q.type==="slider"?q.text.trim()&&Number.isInteger(Number(q.start))&&Number.isInteger(Number(q.end))&&Number(q.start)>=1&&Number(q.end)>=Number(q.start)&&Number(q.end)<=Number.MAX_SAFE_INTEGER&&Number.isFinite(Number(q.correctValue))&&Number(q.correctValue)>=Number(q.start)&&Number(q.correctValue)<=Number(q.end)&&sliderInfo(q).count>=2&&q.time>=10&&q.time<=120&&Number.isInteger(q.time):q.text.trim()&&q.a.every(x=>x.trim())&&q.correct>=0&&q.time>=5&&q.time<=120&&Number.isInteger(q.time);
const valid=()=>Q.title.trim()&&Q.questions.length&&Q.questions.every(qOk);
function editorView(){
 applyTheme(Q.theme);
 A.innerHTML=`<header class="ed"><div class="editor-title-wrap">${ADMIN_EDIT?`<span class="admin-edit-badge">⚙ Sitebeheer</span>`:""}<input class="qtitle" data-f="title" placeholder="Naam van de quiz" value="${esc(Q.title)}"><button class="btn w sm settings-btn" data-a="settings">⚙ Instellingen</button></div><span><button class="btn w sm" data-a="exit">Sluiten</button> <button id="sv" class="btn g sm" data-a="save" title="Vul alles in om op te slaan">Opslaan</button></span></header>
 <div class="theme-strip"><span class="theme-strip-icon">${THEMES[safeTheme(Q.theme)].icon}</span><b>${esc(THEMES[safeTheme(Q.theme)].name)}</b><small>Dit thema zie je tijdens het spelen op het scherm van de host en op telefoons.</small></div>
 <div class="edw"><aside id="side"></aside><section id="main"></section></div>`;side();mainQ();saveBtn();wireThemePreviews()}
function side(){
 const total=Q.questions.length;
 const items=[];
 Q.questions.forEach((q,i)=>{
   const typeLabel=q.type==="tf"?"Waar/niet waar":q.type==="dia"?"Dia":q.type==="typing"?"Typen":q.type==="slider"?"Schuifregelaar":"Quiz";
   items.push(`<div class="thumb ${i==SEL?"on":""}" data-a="sel" data-i="${i}" draggable="true" data-drag-index="${i}" title="Sleep om de volgorde te veranderen"><div class="drag-handle" aria-hidden="true">⠿</div><small>${i+1} ${typeLabel} ${qOk(q)?"":'<span class="bad">! onvolledig</span>'}</small><div class="tt">${esc(q.text)||"Nieuwe vraag"}${q.doublePoints?'<span class="mini-double">2×</span>':""}</div><button class="x" data-a="dq" data-i="${i}" aria-label="Vraag verwijderen">×</button></div>`);
   if(i<total-1){
     const checked=q.leaderboard!==false;
     items.push(`<div class="side-leaderboard-gap"><label class="side-leaderboard-between ${checked?"is-on":""}" data-i="${i}" aria-label="Tussenstand na vraag ${i+1}"><span class="side-check"><input type="checkbox" data-i="${i}" ${checked?"checked":""} aria-label="Tussenstand na vraag ${i+1}"><b></b></span><span class="side-leaderboard-copy"><b>Leaderboard na vraag ${i+1}</b><small>${checked?"Tussenstand tonen voordat de volgende vraag start":"Geen tussenstand na deze vraag"}</small></span></label></div>`);
   }
 });
 $("#side").innerHTML=items.join("")+`<button class="btn b side-add-question" data-a="newq">+ Vraag toevoegen</button>`;
}
function mainQ(){
 const q=Q.questions[SEL];
 if(!q)return $("#main").innerHTML=`<div class="empty"><div class="big-msg">Nog geen vragen</div><p>Voeg je eerste vraag toe.</p><button class="btn b" data-a="newq">+ Vraag toevoegen</button></div>`;
 if(q.type==="dia"){$("#main").innerHTML=`<div class="slide-editor card"><div class="type-badge dia">🖼️ DIA</div><input class="qbig" data-f="text" placeholder="Titel van de dia" value="${esc(q.text)}"><textarea class="qinfo" data-f="info" rows="8" placeholder="Schrijf hier de informatie die je wilt laten zien...">${esc(q.info||"")}</textarea><div class="opts"><label>Duur van de dia (5-120 sec)<input type="number" min="5" max="120" data-f="time" value="${q.time}"></label></div><div class="slide-preview"><div class="slide-kicker">DIA</div><h2>${esc(q.text)||"Jouw titel"}</h2><p>${esc(q.info)||"Jouw informatie verschijnt hier."}</p></div></div>`;return}
 if(q.type==="slider"){const si=sliderInfo(q);const correct=Number.isFinite(Number(q.correctValue))?Number(q.correctValue):sliderCorrectValue(q);$("#main").innerHTML=`<div class="slider-editor"><div class="type-badge slider">↔️ SCHUIFREGELAAR</div><input class="qbig" data-f="text" placeholder="Typ hier je vraag" value="${esc(q.text)}"><div class="slider-settings-grid"><label>Begin nummer<input type="number" min="1" max="9007199254740991" step="1" data-f="start" value="${Number.isFinite(Number(q.start))?q.start:1}"></label><label>Eind nummer<input type="number" min="1" max="9007199254740991" step="1" data-f="end" value="${Number.isFinite(Number(q.end))?q.end:100}"></label><label>Tijd (10-120 sec)<input type="number" min="10" max="120" data-f="time" value="${q.time}"></label></div><div class="slider-correct-box"><b>Juiste antwoord</b><input class="slider-correct-input" type="number" min="${Number(q.start)||1}" max="${Number(q.end)||100}" step="1" data-f="correctValue" value="${Number.isFinite(correct)?correct:""}" placeholder="Typ het juiste cijfer"><small>Spelers zien alleen de automatisch berekende, afgeronde waarden op de schuifregelaar. De interne stapgrootte blijft verborgen.</small></div><div class="opts"><div class="fixed-points"><span>Punten</span><b>1000</b><small>90% op afstand, 10% op tijd. Tijd telt veel minder zwaar mee.</small></div><button class="btn ${q.doublePoints?"g":"w"} double-toggle ${q.doublePoints?"active":""}" data-a="double">${q.doublePoints?"✓ ":""}Dubbele punten</button></div></div>`;return}
 if(q.type==="typing"){$("#main").innerHTML=`<div class="type-badge typing">⌨️ TYPEN</div><input class="qbig" data-f="text" placeholder="Typ hier je vraag" value="${esc(q.text)}">
 <div class="opts"><label>Tijd om te antwoorden (5-120 sec)<input type="number" min="5" max="120" data-f="time" value="${q.time}"></label><div class="fixed-points"><span>Vaste punten</span><b>1000</b><small>Maximaal 1000 • daalt per milliseconde</small></div><button class="btn ${q.doublePoints?"g":"w"} double-toggle ${q.doublePoints?"active":""}" data-a="double" title="${q.doublePoints?"Dubbele punten staan aan":"Dubbele punten staan uit"}">${q.doublePoints?"✓ ":""}Dubbele punten</button></div>
 <div class="typing-answers card"><div class="typing-answer-head"><div><b>Goede antwoorden</b><small>Hoofdletters en leestekens worden genegeerd.</small></div><button class="btn b sm" data-a="addtypeanswer">+ Antwoord toevoegen</button></div><div class="typing-answer-list">${q.a.map((t,i)=>`<div class="typing-answer-row"><span class="typing-index">${i+1}</span><input data-f="a" data-i="${i}" maxlength="160" placeholder="Goed antwoord ${i+1}" value="${esc(t)}"><button class="btn w sm icon-btn" data-a="deltypeanswer" data-i="${i}" ${q.a.length<=1?"disabled":""} aria-label="Antwoord verwijderen">×</button></div>`).join("")}</div></div>
 <p class="typing-help">Elke ingevulde regel telt als een goed antwoord. Je kunt onbeperkt mogelijke antwoorden toevoegen. <b>Punten zijn altijd 1000.</b></p>`;return}
 $("#main").innerHTML=`<div class="type-badge ${q.type==="tf"?"tf":"quiz"}">${q.type==="tf"?"✓ ✗ WAAR OF NIET WAAR":"▲ QUIZVRAAG"}</div><input class="qbig" data-f="text" placeholder="Typ hier je vraag" value="${esc(q.text)}">
 <div class="opts"><label>Tijd om te antwoorden (5-120 sec)<input type="number" min="5" max="120" data-f="time" value="${q.time}"></label><div class="fixed-points"><span>Vaste punten</span><b>1000</b><small>Maximaal 1000 • daalt per milliseconde</small></div><button class="btn ${q.doublePoints?"g":"w"} double-toggle ${q.doublePoints?"active":""}" data-a="double" title="${q.doublePoints?"Dubbele punten staan aan":"Dubbele punten staan uit"}">${q.doublePoints?"✓ ":""}Dubbele punten</button></div>
 <div class="agrid ${q.type==="tf"?"tf":""}">${q.type==="tf"?q.a.map((t,i)=>`<div class="ans ${["g","r"][i]}"><span>${["✓","✗"][i]}</span><em>${esc(t)}</em><label class="chk" title="Goed antwoord"><input type="radio" name="ok" data-f="correct" data-i="${i}" ${q.correct==i?"checked":""}><b></b></label></div>`).join(""):q.a.map((t,i)=>`<div class="ans ${COL[i]}"><span>${SYM[i]}</span><input data-f="a" data-i="${i}" placeholder="Antwoord ${"ABCD"[i]}" value="${esc(t)}"><label class="chk" title="Goed antwoord"><input type="radio" name="ok" data-f="correct" data-i="${i}" ${q.correct==i?"checked":""}><b></b></label></div>`).join("")}</div>
 <p style="color:var(--ink)">Selecteer het rondje bij het goede antwoord. <b>Punten zijn altijd 1000.</b></p>`}
const saveBtn=()=>{const b=$("#sv");if(b)b.disabled=!valid()};
document.addEventListener("input",e=>{const t=e.target,f=t.dataset.f;if(!f||!Q)return;const q=Q.questions[SEL];if(!q&&f!="title")return;
 if(f=="settingsTitle"){Q.title=t.value;const qt=document.querySelector(".qtitle");if(qt)qt.value=t.value;saveBtn();return;}
 if(f=="settingsDescription"){Q.description=t.value;return;}
 if(f=="title")Q.title=t.value;else if(f=="text")q.text=t.value;else if(f=="info")q.info=t.value;else if(f=="time")q.time=t.value===""?NaN:+t.value;
 else if(f=="a")q.a[+t.dataset.i]=t.value;else if(f=="correct")q.correct=+t.dataset.i;else if(f=="start")q.start=Math.max(1,Math.floor(+t.value||0));else if(f=="end")q.end=Math.max(1,Math.floor(+t.value||0));else if(f=="correctStep")q.correctStep=+t.value;else if(f=="correctValue")q.correctValue=t.value===""?NaN:+t.value;
 side();saveBtn()});
document.addEventListener("input",e=>{if(e.target?.id==="sliderInput"){const q=G&&QS()[G.q],el=$("#sliderPlayValue");if(el&&q?.type==="slider")el.textContent=String(sliderValue(q,+e.target.value));return}});
document.addEventListener("change",e=>{const f=e.target?.dataset?.f;if(Q&&f==="correctValue"){Q.questions[SEL].correctValue=e.target.value===""?NaN:+e.target.value;saveBtn();return}if(Q&&f==="correctStep"){Q.questions[SEL].correctStep=+e.target.value;saveBtn();return}if(Q&&(f==="start"||f==="end")&&Q.questions[SEL]?.type==="slider"){Q.questions[SEL][f]=Math.max(1,Math.floor(+e.target.value||0));mainQ();saveBtn();return}
 const cb=e.target.closest?.(".side-leaderboard-between input[type=\"checkbox\"]");
 if(!cb||!Q)return;
 const i=Number(cb.dataset.i);
 const q=Q.questions[i];
 if(!q||i>=Q.questions.length-1)return;
 q.leaderboard=cb.checked;
 side();
 saveBtn();
});
act.sel=d=>{SEL=+d.i;side();mainQ()};
act.dq=d=>{Q.questions.splice(+d.i,1);SEL=Math.min(SEL,Q.questions.length-1);side();mainQ();saveBtn()};
act.settings=()=>{
 const m=document.createElement("div");m.className="modal";
 const current=safeTheme(Q.theme);
 m.innerHTML=`<div class="card settings-card"><div class="picker-head"><div><span class="eyebrow">QUIZ INSTELLINGEN</span><h2>Instellingen</h2><p>Pas de naam en het uiterlijk van je quiz aan.</p></div><button class="btn w sm picker-close" data-a="closem">×</button></div>
 <label class="settings-field"><span>Naam van de quiz</span><input id="settingsTitle" data-f="settingsTitle" maxlength="60" value="${esc(Q.title)}" placeholder="Naam van de quiz"></label>
 <label class="settings-field"><span>Beschrijving van de quiz</span><textarea id="settingsDescription" data-f="settingsDescription" rows="5" maxlength="500" placeholder="Waar gaat deze quiz over?">${esc(Q.description||"")}</textarea><small class="settings-help">Deze beschrijving is zichtbaar in Ontdek quizzen wanneer je quiz openbaar is.</small></label>
 <div class="visibility-setting"><div><b>🌍 Zichtbaarheid</b><small>Kies of andere spelers deze quiz in <b>Ontdek quizzen</b> mogen zien. Standaard is een quiz openbaar.</small></div><div class="visibility-switch" role="group" aria-label="Zichtbaarheid van de quiz"><button class="visibility-option ${Q.public!==false?"active":""}" data-a="visibilityPick" data-value="public">🌍 Openbaar</button><button class="visibility-option ${Q.public===false?"active":""}" data-a="visibilityPick" data-value="private">🔒 Privé</button></div><div class="visibility-note ${Q.public===false?"private":"public"}" id="visibilityNote">${Q.public===false?"Alleen jij kunt deze quiz zien en bewerken.":"Iedereen kan deze quiz vinden, bekijken en spelen."}</div></div>
 <div class="settings-section"><div class="settings-label"><b>Achtergrondthema</b><small>Kies 1 van de 25 stijlen. Je ziet de echte achtergrond als preview; die wordt tijdens het spelen op host én speler gebruikt.</small></div><div class="theme-grid">${themeIds.map(id=>`<button class="theme-choice ${id===current?"selected":""}" data-a="themePick" data-theme="${id}"><img class="theme-choice-thumb" data-theme="${id}" src="${themeAsset(id,"jpg")}" alt="${esc(THEMES[id].name)} voorbeeld" decoding="async"><span class="theme-choice-meta"><b>${esc(THEMES[id].name)}</b><small>${id===current?"✓ Geselecteerd":"Thema kiezen"}</small></span></button>`).join("")}</div></div>
 <div class="settings-actions"><button class="btn w" data-a="closem">Annuleren</button><button class="btn g" data-a="saveSettings">Instellingen opslaan</button></div></div>`;
 document.body.append(m);
 wireThemePreviews();
};
act.themePick=d=>{Q.theme=safeTheme(d.theme);document.querySelectorAll(".theme-choice").forEach(x=>x.classList.toggle("selected",x.dataset.theme===Q.theme));applyTheme(Q.theme);const strip=document.querySelector(".theme-strip");if(strip){strip.querySelector(".theme-strip-icon").textContent=THEMES[Q.theme].icon;strip.querySelector("b").textContent=THEMES[Q.theme].name}};
act.visibilityPick=d=>{Q.public=d.value!=="private";document.querySelectorAll(".visibility-option").forEach(x=>x.classList.toggle("active",(x.dataset.value==="public")===Q.public));const n=$("#visibilityNote");if(n){n.className="visibility-note "+(Q.public?"public":"private");n.textContent=Q.public?"Iedereen kan deze quiz vinden, bekijken en spelen.":"Alleen jij kunt deze quiz zien en bewerken."}saveBtn();};
act.saveSettings=()=>{const input=$("#settingsTitle"),desc=$("#settingsDescription");const name=input?.value.trim();if(!name)return toast("Geef je quiz een naam.");Q.title=name;Q.description=(desc?.value||"").trim();applyTheme(Q.theme);document.querySelector(".qtitle")&&(document.querySelector(".qtitle").value=name);act.closem();saveBtn();side()};
let dragIndex=-1;
document.addEventListener("dragstart",e=>{const t=e.target.closest("[data-drag-index]");if(!t||!Q)return;dragIndex=+t.dataset.dragIndex;t.classList.add("dragging");e.dataTransfer.effectAllowed="move";e.dataTransfer.setData("text/plain",String(dragIndex))});
document.addEventListener("dragend",e=>{e.target.closest("[data-drag-index]")?.classList.remove("dragging");dragIndex=-1;document.querySelectorAll("[data-drag-index].drag-over").forEach(x=>x.classList.remove("drag-over"))});
document.addEventListener("dragover",e=>{const t=e.target.closest("[data-drag-index]");if(!t||!Q||dragIndex<0)return;e.preventDefault();document.querySelectorAll("[data-drag-index].drag-over").forEach(x=>x.classList.remove("drag-over"));t.classList.add("drag-over")});
document.addEventListener("dragleave",e=>{const t=e.target.closest("[data-drag-index]");if(t&&!t.contains(e.relatedTarget))t.classList.remove("drag-over")});
document.addEventListener("drop",e=>{const t=e.target.closest("[data-drag-index]");if(!t||!Q||dragIndex<0)return;e.preventDefault();const to=+t.dataset.dragIndex;if(dragIndex===to)return;const moved=Q.questions.splice(dragIndex,1)[0];Q.questions.splice(to,0,moved);SEL=Q.questions.indexOf(moved);side();mainQ();saveBtn();dragIndex=-1});
let pointerDrag={active:false,start:-1,target:-1,timer:null};
const clearPointerDrag=()=>{if(pointerDrag.timer)clearTimeout(pointerDrag.timer);document.querySelectorAll(".thumb.pointer-drag,.thumb.drag-over").forEach(x=>x.classList.remove("pointer-drag","drag-over"));pointerDrag={active:false,start:-1,target:-1,timer:null}};
document.addEventListener("pointerdown",e=>{const h=e.target.closest(".drag-handle"),t=h?.closest("[data-drag-index]");if(!h||!t||!Q)return;const start=+t.dataset.dragIndex;pointerDrag={active:false,start,target:-1,timer:setTimeout(()=>{pointerDrag.active=true;t.classList.add("pointer-drag");try{t.setPointerCapture(e.pointerId)}catch(_){}} ,180)} });
document.addEventListener("pointermove",e=>{if(pointerDrag.start<0)return;if(!pointerDrag.timer&&!pointerDrag.active)return;const t=document.elementFromPoint(e.clientX,e.clientY)?.closest?.("[data-drag-index]");if(!t||!Q)return;if(!pointerDrag.active)return;pointerDrag.target=+t.dataset.dragIndex;document.querySelectorAll(".thumb.drag-over").forEach(x=>x.classList.remove("drag-over"));if(pointerDrag.target!==pointerDrag.start)t.classList.add("drag-over")});
document.addEventListener("pointerup",e=>{if(pointerDrag.start<0){clearPointerDrag();return}if(pointerDrag.active&&pointerDrag.target>=0&&pointerDrag.target!==pointerDrag.start&&Q){const from=pointerDrag.start,to=pointerDrag.target,moved=Q.questions.splice(from,1)[0];Q.questions.splice(to,0,moved);SEL=Q.questions.indexOf(moved);side();mainQ();saveBtn()}clearPointerDrag()});
document.addEventListener("pointercancel",clearPointerDrag);
act.newq=async()=>{await loadSiteConfig();const m=document.createElement("div");m.className="modal";
const card=document.createElement("div");card.className="card type-picker";
const head=document.createElement("div");head.className="picker-head";
const intro=document.createElement("div");
const eyebrow=document.createElement("span");eyebrow.className="eyebrow";eyebrow.textContent="NIEUWE INHOUD";
const title=document.createElement("h2");title.textContent="Kies een vraagtype";
const desc=document.createElement("p");desc.textContent="Vraagtypes die offline staan kunnen hier niet worden toegevoegd.";
intro.append(eyebrow,title,desc);
const close=document.createElement("button");close.className="btn w sm picker-close";close.dataset.a="closem";close.textContent="×";
head.append(intro,close);
const grid=document.createElement("div");grid.className="type-grid";
const makeOption=(cls,action,type,art,artClass,name,descText,chip)=>{const b=document.createElement("button");b.className=`type-option ${cls}`;b.dataset.a=action;b.disabled=!typeOnline(type);const artWrap=document.createElement("span");artWrap.className=`type-art ${artClass||""}`;if(Array.isArray(art)){art.forEach((x,i)=>{const a=document.createElement("span");a.className=x.className||"";a.textContent=x.text;artWrap.append(a)})}else{artWrap.textContent=art}const n=document.createElement("span");n.className="type-name";n.textContent=name;if(SITE_CFG.questionTypes?.[type]?.new){const nb=document.createElement("i");nb.className="site-new-badge";nb.textContent="NIEUW";b.append(nb)}const d=document.createElement("span");d.className="type-desc";d.textContent=descText;const c=document.createElement("span");c.className="type-chip";c.textContent=chip;b.append(artWrap,n,d,c);return b};
if(typeOnline("quiz"))grid.append(makeOption("blue","addq","quiz",[{text:"▲",className:"art-shape"},{text:"◆",className:"art-shape small"},{text:"●",className:"art-shape tiny"}],"","Quizvraag","4 antwoorden • 1000 punten • snel spelen","QUIZ"));
if(typeOnline("tf"))grid.append(makeOption("green","addtf","tf",[{text:"✓"},{text:"✕"}],"tf-art","Waar of niet waar","2 keuzes • 1000 punten • simpel en snel","WAAR / NIET WAAR"));
if(typeOnline("dia"))grid.append(makeOption("purple","adddia","dia","🖼️","dia-art","Dia","Titel + informatie • geen antwoord • geen punten","DIA"));
if(typeOnline("typing"))grid.append(makeOption("orange","addtyping","typing","⌨️","typing-art","Typen","Speler typt woord of zin • 1000 punten • zoveel goede antwoorden als je wilt","TYPEN"));
if(typeOnline("slider"))grid.append(makeOption("purple","addslider","slider","↔️","slider-art","Schuifregelaar","Kies een getal op een schaal • maximaal 100 stappen • vooral punten op afstand","SCHUIVEN"));
if(!grid.children.length){const empty=document.createElement("div");empty.className="type-empty";empty.textContent="Er zijn momenteel geen vraagtypes online.";grid.append(empty)}card.append(head,grid);m.append(card);document.body.append(m)};
act.closem=()=>document.querySelector(".modal")?.remove();
const addQ=t=>{act.closem();Q.questions.push(newQ(t));SEL=Q.questions.length-1;side();mainQ();saveBtn()};
act.addq=()=>typeOnline("quiz")?addQ("quiz"):toast("Quizvraag staat offline.");
act.addtf=()=>typeOnline("tf")?addQ("tf"):toast("Waar/niet waar staat offline.");
act.adddia=()=>typeOnline("dia")?addQ("dia"):toast("Dia staat offline.");
act.addtyping=()=>typeOnline("typing")?addQ("typing"):toast("Typen staat offline.");
act.addslider=()=>typeOnline("slider")?addQ("slider"):toast("Schuifregelaar staat offline.");
act.double=()=>{const q=Q.questions[SEL];if(!q||q.type==="dia")return;q.doublePoints=!q.doublePoints;mainQ();side()};
act.addtypeanswer=()=>{const q=Q.questions[SEL];if(!q||q.type!=="typing")return;q.a.push("");mainQ();setTimeout(()=>document.querySelector('.typing-answer-row:last-child input')?.focus(),0);saveBtn()};
act.deltypeanswer=d=>{const q=Q.questions[SEL];if(!q||q.type!=="typing"||q.a.length<=1)return;q.a.splice(+d.i,1);mainQ();saveBtn()};
act.exit=()=>{if(confirm("Sluiten zonder opslaan?")){const fromAdmin=!!ADMIN_EDIT;Q=null;QID=null;ADMIN_EDIT=null;if(fromAdmin){act.admin();}else{tab="mine";home()}}};
act.save=async()=>{if(!valid())return;const ownerId=ADMIN_EDIT?.ownerId||user.uid;const id=QID||push(ref(db,"quizzes/"+ownerId)).key;
 const originalCreator=Q.creatorName||user.displayName||"Quizzo speler";
 const payload={title:Q.title.trim(),description:String(Q.description||"").trim(),theme:safeTheme(Q.theme),public:Q.public!==false,creatorName:originalCreator,questions:Q.questions.map(normalizeQuestion),updated:Date.now()};
 try{await set(ref(db,`quizzes/${ownerId}/${id}`),payload)}catch(e){return toast(em(e))}
 const fromAdmin=!!ADMIN_EDIT;Q=null;ADMIN_EDIT=null;QID=null;if(fromAdmin){toast("Quiz van gebruiker bijgewerkt!");act.admin();return;}tab="mine";home();toast("Quiz opgeslagen!")};

/* ---------- Game ---------- */
const cols=q=>q.type=="tf"?["g","r"]:COL,syms=q=>q.type=="tf"?["✓","✗"]:SYM;
const INTRO_MS=5000,DOUBLE_BONUS_INTRO_MS=2500;
const randomCode=async()=>{let code;do{code=String(Math.floor(100000+Math.random()*900000))}while((await get(ref(db,"games/"+code))).exists());return code};
const createGame=async(qz,gameMode,playerProfile=null)=>{await loadSiteConfig();if(!gameOnline(gameMode))throw new Error(`${gameMode==="solo"?"Alleen spelen":"Multiplayer"} staat momenteel offline.`);if(arr(qz?.questions).some(q=>!typeOnline(q.type)))throw new Error("Deze quiz gebruikt een vraagtype dat momenteel offline staat.");const code=await randomCode();const solo=gameMode=="solo";const questions=arr(qz.questions).map(normalizeQuestion);const first=questions[0];const firstIsSlide=first?.type==="dia";const data={host:user.uid,mode:gameMode,createdAt:Date.now(),lastActiveAt:Date.now(),state:solo?(firstIsSlide?"slide":"countdown"):"lobby",q:0,countdownStartedAt:solo&&!firstIsSlide?serverTimestamp():null,startedAt:solo&&firstIsSlide?serverTimestamp():null,quiz:{title:qz.title,theme:safeTheme(qz.theme),questions}};if(solo){const profile=normalizeProfile(playerProfile||savedProfile());data.players={[user.uid]:{name:user.displayName||user.email,score:0,...profile}};}await set(ref(db,"games/"+code),data);return code};
act.host=async d=>{try{await loadSiteConfig();if(!gameOnline("multiplayer"))return toast("Multiplayer staat momenteel offline.");const qz=(await get(ref(db,`quizzes/${user.uid}/${d.id}`))).val();if(!qz)return toast("Deze quiz kon niet worden geladen.");if(arr(qz.questions).some(q=>!typeOnline(q.type)))return toast("Deze quiz gebruikt een vraagtype dat momenteel offline staat.");const code=await createGame(qz,"multiplayer");run(code,true)}catch(e){toast(em(e))}};
act.playhost=async d=>{act.closem();act.host(d)};
act.solo=async d=>{act.closem();try{await loadSiteConfig();if(!gameOnline("solo"))return toast("Alleen spelen staat momenteel offline.");const qz=(await get(ref(db,`quizzes/${user.uid}/${d.id}`))).val();if(!qz)return toast("Deze quiz kon niet worden geladen.");if(arr(qz.questions).some(q=>!typeOnline(q.type)))return toast("Deze quiz gebruikt een vraagtype dat momenteel offline staat.");openAvatarPicker(savedProfile(),async profile=>{const code=await createGame(qz,"solo",profile);run(code,true)},"Kies je avatar")}catch(e){toast(em(e))}};
function run(code,host){cleanup();CODE=code;HOST=host;
 unsub=onValue(ref(db,"games/"+code),s=>{G=s.val();if(!G){if(!host&&CODE)toast("De quiz is afgesloten.");return home()}paint()});
 timer=setInterval(tick,250)}
const QS=()=>arr(G.quiz.questions).map(q=>({...q,a:arr(q.a)})),P=()=>Object.entries(G.players||{}).map(([id,p])=>({id,...p,...normalizeProfile(p)}));
const ANS=()=>G.answers?.[G.q]||{},MAX_POINTS=1000,pointsFor=q=>q.type==="dia"?0:MAX_POINTS*(q.doublePoints?2:1),earnedPointsFor=(q,answerAt)=>{if(q.type==="dia"||!Number.isFinite(answerAt))return 0;const started=Number(G.startedAt);const total=Math.max(1,Number(q.time)*1000);const remaining=Math.max(0,Math.min(total,started+total-Number(answerAt)));const base=Math.floor(MAX_POINTS*remaining/total);return base*(q.doublePoints?2:1)},introDuration=q=>INTRO_MS+(q.type!=="dia"&&q.doublePoints?DOUBLE_BONUS_INTRO_MS:0),end=()=>G.startedAt+QS()[G.q].time*1000,introEnd=()=>G.countdownStartedAt+introDuration(QS()[G.q]),isSlide=()=>QS()[G.q]?.type==="dia",isTyping=()=>QS()[G.q]?.type==="typing";
const normalizeAnswer=v=>String(v??"").normalize("NFKC").toLocaleLowerCase("nl-NL").replace(/[^\p{L}\p{N}\s]/gu," ").replace(/\s+/g," ").trim();
const typingCorrect=(q,a)=>{const value=normalizeAnswer(a?.v??a?.value??"");return !!value&&q.a.some(x=>normalizeAnswer(x)===value)};
const sliderScore=(q,a)=>{const si=sliderInfo(q);if(!si.count||!Number.isFinite(Number(a?.v)))return 0;const chosen=sliderValue(q,+a.v),correct=sliderCorrectValue(q),span=Math.max(1,Number(q.end)-Number(q.start)),distance=Math.abs(chosen-correct),proximity=Math.max(0,1-distance/span);const total=Math.max(1,Number(q.time)*1000),remaining=Math.max(0,Math.min(total,Number(G.startedAt)+total-Number(a?.t)));const timeFactor=remaining/total;const base=Math.floor(MAX_POINTS*proximity*(0.9+0.1*timeFactor));return base*(q.doublePoints?2:1)};
const setTimerBar=(el,ratio)=>{
 if(!el)return;
 const r=Math.max(0,Math.min(1,ratio));
 el.style.width=(r*100)+"%";
 el.classList.remove("timer-warn","timer-danger");
 if(r<=0.22)el.classList.add("timer-danger");
 else if(r<=0.5)el.classList.add("timer-warn");
};
function tick(){
 if(!G)return;
 if(G.state==="countdown"){
  const qIntro=QS()[G.q];
  if(qIntro?.type==="dia"){
   if(HOST&&!busy){busy=true;update(ref(db,"games/"+CODE),{state:"slide",countdownStartedAt:null,startedAt:serverTimestamp()}).catch(e=>toast(em(e))).finally(()=>busy=false)}
   return;
  }
  const dur=introDuration(qIntro),ms=introEnd()-now(),el=$("#introTm");if(el)el.textContent=Math.max(0,Math.ceil(ms/1000));
  const b=$("#introBar");setTimerBar(b,ms/dur);
  if(HOST&&ms<=0&&!busy){busy=true;update(ref(db,"games/"+CODE),{state:"question",startedAt:serverTimestamp()}).catch(e=>toast(em(e))).finally(()=>busy=false)}
  return;
 }
 if(G.state==="slide"){
  const q=QS()[G.q],ms=end()-now(),el=$("#slideTm");
  if(el)el.textContent=Math.max(0,Math.ceil(ms/1000));
  const b=$("#slideBar");setTimerBar(b,ms/(q.time*1000));
  if(HOST&&ms<=0&&!busy){busy=true;Promise.resolve(act.next()).catch(e=>toast(em(e))).finally(()=>busy=false)}
  return;
 }
 if(G.state!="question")return;
 const q=QS()[G.q],ms=end()-now(),el=$("#tm");
 if(el)el.textContent=Math.max(0,Math.ceil(ms/1000));
 const b=$("#tb");setTimerBar(b,ms/(q.time*1000));
 if(HOST&&(ms<=0||(P().length&&Object.keys(ANS()).length>=P().length)))reveal()}
async function reveal(){if(busy)return;busy=true;const q=QS()[G.q];
 const ans=(await get(ref(db,`games/${CODE}/answers/${G.q}`))).val()||{},u={state:"reveal"};
 P().forEach(p=>{const a=ans[p.id];const ok=q.type==="slider"?!!a&&a.t<=end()+1500&&Number.isFinite(Number(a.v)):q.type==="typing"?!!a&&a.t<=end()+1500&&typingCorrect(q,a):!!a&&a.c===q.correct&&a.t<=end()+1500;const earned=q.type==="slider"?(ok?sliderScore(q,a):0):(ok?earnedPointsFor(q,Number(a?.t)):0);u[`players/${p.id}/ok`]=ok;u[`players/${p.id}/earnedPoints`]=earned;u[`players/${p.id}/score`]=(p.score||0)+earned});
 await update(ref(db,"games/"+CODE),u)}
act.start=()=>{const q=QS()[0];return q?.type==="dia"?update(ref(db,"games/"+CODE),{state:"slide",q:0,countdownStartedAt:null,startedAt:serverTimestamp()}):update(ref(db,"games/"+CODE),{state:"countdown",q:0,countdownStartedAt:serverTimestamp(),startedAt:null})};
const startQuestion=(ni)=>{
 if(ni>=QS().length)return remove(ref(db,"games/"+CODE));
 const nq=QS()[ni];
 return nq.type==="dia"
  ?update(ref(db,"games/"+CODE),{state:"slide",q:ni,countdownStartedAt:null,startedAt:serverTimestamp()})
  :update(ref(db,"games/"+CODE),{state:"countdown",q:ni,countdownStartedAt:serverTimestamp(),startedAt:null});
};
act.next=()=>{
 if(G.state==="slide"){
  const q=QS()[G.q],last=G.q+1>=QS().length;
  if(last)return remove(ref(db,"games/"+CODE));
  return q.leaderboard===false?startQuestion(G.q+1):update(ref(db,"games/"+CODE),{state:"board"});
 }
 if(G.state==="reveal"){
  const q=QS()[G.q],last=G.q+1>=QS().length;
  if(last)return remove(ref(db,"games/"+CODE));
  return q.leaderboard===false?startQuestion(G.q+1):update(ref(db,"games/"+CODE),{state:"board"});
 }
 if(G.state=="board")return startQuestion(G.q+1);
};
act.close=()=>remove(ref(db,"games/"+CODE));
act.ans=d=>{if(G.state!="question"||now()>end()||ANS()[user.uid])return;const q=QS()[G.q];if(q.type==="typing")return act.typingSubmit();if(q.type==="slider")return act.sliderSubmit();set(ref(db,`games/${CODE}/answers/${G.q}/${user.uid}`),{c:+d.i,t:now()})};
act.sliderSubmit=()=>{if(G.state!=="question"||now()>end()||ANS()[user.uid]||QS()[G.q]?.type!=="slider")return;const input=$("#sliderInput");if(input)set(ref(db,`games/${CODE}/answers/${G.q}/${user.uid}`),{v:+input.value,t:now()})};
act.typingSubmit=()=>{if(G.state!=="question"||now()>end()||ANS()[user.uid]||!isTyping())return;const input=$("#typingInput");const value=input?.value?.trim()||"";if(!value)return toast("Typ eerst een antwoord in.");set(ref(db,`games/${CODE}/answers/${G.q}/${user.uid}`),{v:value,t:now()})};
document.addEventListener("submit",e=>{if(e.target?.id==="typingForm"){e.preventDefault();act.typingSubmit()}});
const sorted=()=>P().sort((a,b)=>(b.score||0)-(a.score||0));
function rankMap(scores){return Object.fromEntries(P().sort((a,b)=>(scores[b.id]??(b.score||0))-(scores[a.id]??(a.score||0))).map((p,i)=>[p.id,i+1]))}
function currentScoreMap(){return Object.fromEntries(P().map(p=>[p.id,p.score||0]))}
function animateLeaderboard(){
 document.querySelectorAll(".lb-score").forEach(el=>{
  const from=Number(el.dataset.from||0),to=Number(el.dataset.to||0),dur=850,start=performance.now();
  if(from===to){el.textContent=String(to);return}
  const step=t=>{const k=Math.min(1,(t-start)/dur),e=1-Math.pow(1-k,3),v=Math.round(from+(to-from)*e);el.textContent=String(v);if(k<1)requestAnimationFrame(step)};
  requestAnimationFrame(step);
 });
 document.querySelectorAll(".rank-up").forEach((el,i)=>{el.classList.remove("rank-up");void el.offsetWidth;el.classList.add("rank-up")});
}
function boardRows(list){
 const from=boardAnim?.from||{};
 return list.map((p,i)=>{const rank=i+1,prevRank=boardAnim?.ranks?.[p.id]||rank,delta=prevRank-rank,cls=delta>0?" rank-moved-up":"";
  const mood=delta>0?"rankup":delta<0?"overtaken":"";return `<div class="row lb-row${cls}"><span class="lb-name"><b class="lb-rank">${rank}</b>${avatarMarkup(p,40,mood)}<b>${esc(p.name)}</b>${delta>0?`<span class="rank-up">↑ ${delta}</span>`:delta<0?`<span class="rank-down">↓ ${Math.abs(delta)}</span>`:""}</span><span class="lb-score" data-from="${from[p.id]??p.score??0}" data-to="${p.score||0}">${from[p.id]??p.score??0}</span></div>`}).join("")}

function paint(){
 applyTheme(G?.quiz?.theme||"classic");
 if(G.state!="reveal"&&G.state!="countdown"&&G.state!="slide")busy=false;
 const avatarKey=P().map(p=>`${p.id}:${p.avatar}`).join("|");const key=[G.state,G.q,P().length,avatarKey,HOST?Object.keys(ANS()).length:ANS()[user.uid]?1:0].join();if(key==lastKey)return;
 const prevState=lastPaintState,prevScores={...scoreSnapshot},prevRanks={...rankSnapshot};
 lastKey=key;lastPaintState=G.state;
 const currentScores=currentScoreMap();
 if(G.state==="reveal"&&prevState==="question")boardAnim={from:prevScores,ranks:prevRanks};
 const q=G.state=="lobby"?null:QS()[G.q],me=G.players?.[user.uid],rank=sorted().findIndex(p=>p.id==user.uid)+1,SOLO=G.mode=="solo";
 const tiles=(cls,rev)=>{if(q.type==="slider"){const si=sliderInfo(q),ans=Object.values(ANS()),correct=sliderCorrectValue(q);return `<div class="slider-host-panel"><div class="slider-host-scale"><span>${esc(String(q.start))}</span><div class="slider-host-line"><i style="left:${si.count>1?(sliderCorrectIndex(q)/(si.count-1))*100:0}%"></i></div><span>${esc(String(q.end))}</span></div><div class="slider-host-answer">${rev?`Juiste waarde: <b>${esc(String(correct))}</b>`:`Spelers kiezen een waarde op deze schaal.`}</div><small>${ans.filter(a=>Number.isFinite(Number(a?.v))).length} antwoord${ans.filter(a=>Number.isFinite(Number(a?.v))).length===1?"":"en"}</small></div>`;}if(q.type==="typing"){const answered=Object.values(ANS()).filter(a=>a?.v!=null).length;return `<div class="typing-host-panel"><div class="typing-host-icon">⌨️</div><div><h2>${rev?"Goede antwoorden":"Typen"}</h2><p>${rev?q.a.filter(x=>x.trim()).map(x=>`<span class="accepted-chip">${esc(x)}</span>`).join(""):`Spelers typen zelf een woord of zin.`}</p><small>${answered} antwoord${answered===1?"":"en"}</small></div></div>`;}return q.a.map((t,i)=>{const n=Object.values(ANS()).filter(a=>a.c==i).length;return `<div class="ans ${cols(q)[i]} ${rev&&i!=q.correct?"dim":""}><span>${rev&&i==q.correct?"✓":syms(q)[i]}</span><em>${esc(t)}</em>${rev?`<span class="n">${n}</span>`:""}</div>`}).join("")};
 const countdown=(showTitle)=>q.type==="dia"?`<div class="stage countdown-screen dia-countdown"><div class="dia-intro-card"><span class="eyebrow">DIA START</span><div class="dia-intro-title">${esc(q.text)}</div><div class="dia-intro-info">${esc(q.info||"")}</div></div><div class="countdown-layout"><div class="countdown-copy">Dia start in...</div><div class="countdown-number" id="introTm">5</div></div><div class="tbar intro-bar"><div id="introBar"></div></div></div>`:`<div class="stage countdown-screen${q.doublePoints?" has-double":""}">${q.doublePoints?'<div class="double-bonus-pop">2× PUNTEN</div>':""}<div class="countdown-title ${q.doublePoints?"after-bonus":""}">${showTitle?esc(q.text):"Kijk naar de host zijn scherm"}</div><div class="countdown-layout"><div class="countdown-copy">Vraag start in...</div><div class="countdown-number" id="introTm">${q.doublePoints?"8":"5"}</div></div><div class="tbar intro-bar"><div id="introBar"></div></div></div>`;
 const slideView=()=>`<div class="stage slide-view"><div class="slide-card"><div class="slide-kicker">DIA</div><h1>${esc(q.text)}</h1><div class="slide-info">${esc(q.info||"")}</div></div><div class="slide-timer"><div class="tcirc" id="slideTm">${q.time}</div><div class="countdown-copy">Op scherm</div></div><div class="tbar"><div id="slideBar"></div></div></div>`;
 const phoneSuccess=(buttonLabel="")=>`<div class="full ${me?.ok?"ok":"no"} phone-result"><div class="stage"><div class="phone-result-avatar">${avatarMarkup(me,100,me?.ok?"happy":"sad")}</div><div class="result-icon">${me?.ok?"✓":"✕"}</div><div class="big-msg">${me?.ok?"Goed gedaan!":"Helaas!"}</div><div class="result-points">${me?.ok?`+${me?.earnedPoints??0} punten`:"Geen punten"}</div><p>Totaal: ${me?.score||0} punten</p>${buttonLabel?`<button class="btn b result-next" data-a="next">${buttonLabel}</button>`:""}</div></div>`;
 let h="";
 if(HOST&&!SOLO){
  if(G.state=="lobby")h=`<div class="stage"><h2>${esc(G.quiz.title)}</h2><div>Ga naar <b>Quiz joinen</b> en vul de code in</div><div class="code">${CODE}</div><div><b>${P().length}</b> spelers</div><div class="chips">${P().map(p=>`<span class="player-chip">${avatarMarkup(p,34)}<b>${esc(p.name)}</b></span>`).join("")||"Wachten op spelers..."}</div><button class="btn g" data-a="start" ${P().length?"":"disabled"}>Quiz starten</button> <button class="btn w" data-a="close">Annuleren</button></div>`;
  else if(G.state=="countdown")h=countdown(true);
  else if(G.state=="slide")h=slideView();
  else if(G.state=="question")h=ANS()[user.uid]?`<div class="center"><div class="big-msg">Antwoord verstuurd</div>Wachten op de uitslag...</div>`:q.type==="slider"?`<div class="stage answer-screen slider-player"><div class="typing-question"><div class="typing-kicker">↔️ SCHUIFREGELAAR</div><h1>${esc(q.text)}</h1><p>Schuif naar de waarde waarvan jij denkt dat die goed is.</p></div><div class="hbar"><div class="tcirc" id="tm"></div><div class="answer-label">Kies je waarde</div></div><div class="tbar"><div id="tb"></div></div><div class="slider-play-wrap"><div class="slider-play-value" id="sliderPlayValue">${esc(String(sliderValue(q,0)))}</div><input id="sliderInput" class="slider-play" type="range" min="0" max="${Math.max(0,sliderInfo(q).count-1)}" step="1" value="0"><div class="slider-range-labels"><span>${esc(String(sliderValue(q,0)))}</span><span>${esc(String(sliderValue(q,sliderInfo(q).count-1)))}</span></div><button class="btn g slider-submit" data-a="sliderSubmit">Antwoord versturen</button></div></div>`:q.type==="typing"?`<div class="stage answer-screen typing-player"><div class="typing-question"><div class="typing-kicker">⌨️ TYPEN</div><h1>${esc(q.text)}</h1><p>Typ het antwoord zo goed mogelijk.</p></div><div class="hbar"><div class="tcirc" id="tm"></div><div class="answer-label">Typ je antwoord</div></div><div class="tbar"><div id="tb"></div></div><form id="typingForm" class="typing-form"><input id="typingInput" autocomplete="off" maxlength="160" placeholder="Typ hier je antwoord..." autofocus><button class="btn g typing-submit" type="submit">Antwoord versturen</button></form><p class="typing-note">Hoofdletters en leestekens maken niet uit.</p></div>`:`<div class="stage answer-screen"><div class="hbar"><div class="tcirc" id="tm"></div><div class="answer-label">${SOLO?"Kies je antwoord":"Kijk naar de host zijn scherm"}</div></div><div class="tbar"><div id="tb"></div></div><div class="agrid big ${q.type=='tf'?"tf":""}">${q.a.map((t,i)=>`<button class="ans ${cols(q)[i]}" data-a="ans" data-i="${i}"><span>${syms(q)[i]}</span><em>${esc(t)}</em></button>`).join("")}</div></div>`;
  else if(G.state=="reveal"){const ps=P();h=`<div class="stage"><div class="qhead">${esc(q.text)}</div><div class="agrid big ${q.type=='tf'?"tf":""}">${tiles("",true)}</div><div class="two"><div><h3>Goed ✓</h3>${ps.filter(p=>p.ok).map(p=>`${avatarMarkup(p,30,"happy")} ${esc(p.name)}`).join(" · ")||"Niemand"}</div><div><h3>Fout ✗</h3>${ps.filter(p=>!p.ok).map(p=>`${avatarMarkup(p,30,"sad")} ${esc(p.name)}`).join(" · ")||"Niemand"}</div></div><button class="btn b" data-a="next">Volgende</button></div>`}
  else if(G.state=="board")h=`<div class="stage leaderboard"><h1>Tussenstand</h1>${boardRows(sorted().slice(0,5))}<button class="btn b" data-a="next">Volgende vraag</button></div>`;
  else{const t=sorted().slice(0,3);h=`<div class="stage"><h1>Podium 🏆</h1><div class="pod">${[1,0,2].map(i=>t[i]?`<div class="pl"><div class="pn pod-player pod-player-${i+1}" style="--pod-player-delay:${["2s","2.8s","1.2s"][i]}">${avatarMarkup(t[i],72)}<b>${esc(t[i].name)}</b><small>${t[i].score||0}</small></div><div class="blk p${i+1}">${i+1}</div></div>`:"").join("")}</div><button class="btn r" data-a="close">Quiz afsluiten</button></div>`}
 }else{
  if(G.state=="lobby")h=`<div class="center"><div class="game-avatar-large">${avatarMarkup(me,104)}</div><div class="big-msg">Je zit erin, ${esc(me?.name)}!</div><p>Wachten tot de host het spel start</p><button class="btn w" data-a="customizeAvatar">🎨 Avatar aanpassen</button></div>`;
  else if(G.state=="countdown")h=countdown(true);
  else if(G.state=="slide")h=slideView();
  else if(G.state=="question")h=ANS()[user.uid]?`<div class="center"><div class="big-msg">Antwoord verstuurd</div>Wachten op de uitslag...</div>`:q.type==="typing"?`<div class="stage answer-screen typing-player"><div class="typing-question"><div class="typing-kicker">⌨️ TYPEN</div><h1>${esc(q.text)}</h1><p>Typ het antwoord zo goed mogelijk.</p></div><div class="hbar"><div class="tcirc" id="tm"></div><div class="answer-label">${SOLO?"Typ je antwoord":"Typ je antwoord"}</div></div><div class="tbar"><div id="tb"></div></div><form id="typingForm" class="typing-form"><input id="typingInput" autocomplete="off" maxlength="160" placeholder="Typ hier je antwoord..." autofocus><button class="btn g typing-submit" type="submit">Antwoord versturen</button></form><p class="typing-note">Hoofdletters en leestekens maken niet uit.</p></div>`:`<div class="stage answer-screen"><div class="hbar"><div class="tcirc" id="tm"></div><div class="answer-label">${SOLO?"Kies je antwoord":"Kijk naar de host zijn scherm"}</div></div><div class="tbar"><div id="tb"></div></div><div class="agrid big ${q.type=='tf'?"tf":""}">${q.a.map((t,i)=>`<button class="ans ${cols(q)[i]}" data-a="ans" data-i="${i}"><span>${syms(q)[i]}</span><em>${esc(t)}</em></button>`).join("")}</div></div>`;
  else if(G.state=="reveal")h=phoneSuccess(SOLO?(G.q+1<QS().length?(q.leaderboard===false?"Volgende vraag":"Naar tussenstand"):"Podium bekijken"):"");
  else if(G.state=="board")h=SOLO?`<div class="center leaderboard solo-board"><h1>Tussenstand</h1>${boardRows(sorted().slice(0,5))}<button class="btn b" data-a="next">Volgende vraag</button></div>`:`<div class="center"><div class="big-msg">Plek ${rank}</div><div>${me?.score||0} punten</div></div>`;
  else if(SOLO){const t=sorted().slice(0,3);h=`<div class="stage"><h1>Podium 🏆</h1><div class="pod">${[1,0,2].map(i=>t[i]?`<div class="pl"><div class="pn pod-player pod-player-${i+1}" style="--pod-player-delay:${["2s","2.8s","1.2s"][i]}">${avatarMarkup(t[i],72)}<b>${esc(t[i].name)}</b><small>${t[i].score||0}</small></div><div class="blk p${i+1}">${i+1}</div></div>`:"").join("")}</div><button class="btn r" data-a="close">Terug naar mijn quizzen</button></div>`;}
  else h=`<div class="center"><div class="big-msg">${rank<=3?["🥇","🥈","🥉"][rank-1]:""} Plek ${rank}</div><div>${me?.score||0} punten</div><p>Wachten tot de host afsluit...</p></div>`}
 A.innerHTML=h;
 if(G.state==="countdown"&&q.type!=="dia"&&q.doublePoints){setTimeout(()=>$(".countdown-title.after-bonus")?.classList.add("title-live"),DOUBLE_BONUS_INTRO_MS)}
 if(G.state==="board"||G.state==="end")setTimeout(animateLeaderboard,20);
 scoreSnapshot=currentScoreMap();rankSnapshot=rankMap(scoreSnapshot);
 if(G.state==="board")boardAnim=null;
 tick()}

/* ---------- Menu, updatelog en sitebeheer ---------- */
let ADM=null,EDITU=null,UPD={},LOGL=[];
/* Sitebeheer gebruikt bewust alleen RAM/session state: na een refresh is de beheerder automatisch uitgelogd. */
const SITE_DEFAULT={
  avatars:{},
  questionTypes:{quiz:{online:false,new:false},tf:{online:false,new:false},dia:{online:false,new:false},typing:{online:false,new:false},slider:{online:false,new:false}},
  gameTypes:{solo:{online:false,new:false},multiplayer:{online:false,new:false}},
  quizAccess:{}
};
let SITE_CFG=JSON.parse(JSON.stringify(SITE_DEFAULT));
const pad=n=>String(n).padStart(2,"0"),fd=d=>String(d).split("-").reverse().join("-");
const nowDT=()=>{const d=new Date();return{date:`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`,time:`${pad(d.getHours())}:${pad(d.getMinutes())}`}};
const deepSiteMerge=(base,val)=>{
  const out=JSON.parse(JSON.stringify(base));
  const merge=(a,b)=>{if(!b||typeof b!=="object")return a;Object.entries(b).forEach(([k,v])=>{if(v&&typeof v==="object"&&!Array.isArray(v))a[k]=merge(a[k]&&typeof a[k]==="object"?a[k]:{},v);else a[k]=v});return a};
  return merge(out,val||{});
};
async function loadSiteConfig(){try{SITE_CFG=deepSiteMerge(SITE_DEFAULT,(await get(ref(db,"siteSettings"))).val()||{});}catch(_){SITE_CFG=JSON.parse(JSON.stringify(SITE_DEFAULT))}return SITE_CFG}
function typeOnline(type){return !!ADM || SITE_CFG.questionTypes?.[type]?.online===true}
function gameOnline(mode){return !!ADM || SITE_CFG.gameTypes?.[mode]?.online===true}
function quizAllowed(owner,id){const v=SITE_CFG.quizAccess?.[owner]?.[id];return v!==false}
async function loadUpdates(){const v=(await get(ref(db,"updates"))).val()||{};UPD=v;return Object.entries(v).map(([id,u])=>({id,...u})).sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time))}
async function priv(paths){if(!ADM)throw new Error("Geen beheerder ingelogd.");
 const entries=Object.entries(paths||{});
 for(const [path,value] of entries){await set(ref(db,path),value)}
}
const adminFail=(err)=>{console.error("Sitebeheer-opslag mislukt",err);toast(em(err)||"Opslaan mislukt. Je blijft ingelogd in Sitebeheer.");};

function adminOverlay(){
  const c=$("#tc");
  if(!c)return;
  c.className="wrap sitebeheer-inline";
  c.innerHTML=`<div class="quizzo-admin-shell"><header class="quizzo-admin-top"><div><div class="admin-kicker">QUIZZO</div><h1>Sitebeheer</h1><p>Beheer de inhoud en beschikbaarheid van je hele site.</p></div><div class="admin-top-actions"><span class="admin-online-dot">● Sitebeheer actief</span></div></header><nav class="quizzo-admin-tabs" id="adminTabs"></nav><main id="adminPanel" class="quizzo-admin-panel">Laden...</main></div>`;
}
const adminTabLabels={dashboard:"Dashboard",updates:"Updatelog",quizzes:"Openbare quizzen",beheer:"Beheer"};
let adminTab="dashboard";
function renderAdminTabs(){const n=$("#adminTabs");if(!n)return;n.innerHTML=Object.entries(adminTabLabels).map(([k,v])=>`<button class="admin-main-tab ${adminTab===k?"active":""}" data-a="adminTab" data-tab="${k}">${k==="dashboard"?"🏠":k==="updates"?"📢":k==="quizzes"?"🌍":"⚙️"} ${v}</button>`).join("")}
function renderAdminDashboard(){
 const c=$("#adminPanel");if(!c)return;
 c.innerHTML=`<div class="admin-dashboard-grid"><button class="admin-dash-card" data-a="adminTab" data-tab="updates"><span>📢</span><b>Updatelog</b><small>Nieuwe updates plaatsen en bestaande updates aanpassen.</small></button><button class="admin-dash-card" data-a="adminTab" data-tab="quizzes"><span>🌍</span><b>Openbare quizzen</b><small>Bekijk en bewerk iedere opgeslagen quiz.</small></button><button class="admin-dash-card" data-a="adminTab" data-tab="beheer"><span>⚙️</span><b>Beheer</b><small>Avatars, vraagtypes, speltypes en quiztoegang.</small></button></div>`;
}
function renderUpdateLogAdmin(){
 const c=$("#adminPanel");if(!c)return;const l=LOGL;
 c.innerHTML=`<section class="admin-card"><div class="admin-card-head"><div><span class="eyebrow">UPDATES</span><h2>Updatelog</h2><p>Maak hier een nieuwe update of pas een bestaande update aan.</p></div><button class="btn g" data-a="newUpdate">+ Nieuwe update</button></div><div class="admin-update-list">${l.map(u=>`<div class="qcard admin-update-row"><div><b>${esc(u.title)}</b><small>${fd(u.date)} · ${esc(u.time)}</small><p>${esc(u.body).slice(0,180)}${String(u.body||"").length>180?"…":""}</p></div><div><button class="btn b sm" data-a="uedit" data-id="${u.id}">Aanpassen</button> <button class="btn r sm" data-a="udel" data-id="${u.id}">Verwijderen</button></div></div>`).join("")||`<div class="admin-empty">Nog geen updates.</div>`}</div></section>`;
}
function updateEditorHtml(){
 const c=$("#adminPanel"),e=EDITU&&UPD[EDITU],n=nowDT();if(!c)return;
 c.innerHTML=`<section class="admin-card admin-update-editor"><div class="admin-card-head"><div><span class="eyebrow">UPDATEREN</span><h2>${e?"Update aanpassen":"Nieuwe update"}</h2></div><button class="btn w sm" data-a="adminTab" data-tab="updates">← Terug</button></div><label>Titel<input id="ut" maxlength="80" placeholder="Titel van de update" value="${esc(e?.title||"")}"></label><div class="opts"><label>Datum<input id="ud" type="date" value="${e?.date||n.date}"></label><label>Tijd<input id="uh" type="time" value="${e?.time||n.time}"></label></div><label>Beschrijving<textarea id="ub" rows="9" placeholder="Wat is er veranderd?">${esc(e?.body||"")}</textarea><div class="admin-form-actions"><button class="btn g" data-a="usave">${e?"Wijzigingen opslaan":"Update plaatsen"}</button>${e?'<button class="btn w" data-a="ucancel">Annuleren</button>':""}</div></section>`;
}
function settingSwitch(path,value,label){return `<button class="admin-setting-switch ${value?"on":"off"}" data-a="toggleSetting" data-path="${esc(path)}"><span class="switch-dot"></span><b>${value?"ONLINE":"OFFLINE"}</b><span>${esc(label)}</span></button>`}
const qtypeMeta={quiz:["Quizvraag","4 antwoorden"],tf:["Waar of niet waar","2 keuzes"],dia:["Dia","Titel + informatie"],typing:["Typen","Getypt antwoord"],slider:["Schuifregelaar","Kies een waarde op een schaal"]};
const gameMeta={solo:["Alleen spelen","Speler speelt zelfstandig"],multiplayer:["Multiplayer","Host + spelers"]};
async function renderBeheer(){
 const c=$("#adminPanel");if(!c)return;await loadSiteConfig();
 const av=QUIZZO_AVATAR_CATALOG.avatars||[];
 const avatarCards=av.map((x,i)=>{const s=SITE_CFG.avatars?.[i]||{};return `<div class="admin-control-card"><div class="admin-control-main">${avatarMarkup({avatar:i},64)}<div><b>${i+1}. ${esc(x.name||AVATAR_NAMES[i]||"Avatar")}</b><small>${s.online===true?"Beschikbaar voor spelers":"Niet beschikbaar voor spelers"}</small></div></div><div class="admin-control-actions">${settingSwitch(`avatars.${i}.online`,s.online===true,"Beschikbaar")} ${settingSwitch(`avatars.${i}.new`,s.new===true,"Nieuw-badge")}</div></div>`}).join("");
 const qtypes=Object.entries(qtypeMeta).map(([k,m])=>{const s=SITE_CFG.questionTypes?.[k]||{};return `<div class="admin-control-card"><div class="admin-control-main"><div class="admin-control-icon">${k==="quiz"?"▲":k==="tf"?"✓✕":k==="dia"?"🖼️":k==="typing"?"⌨️":"↔️"}</div><div><b>${m[0]}${s.new===true?'<span class="admin-new-badge">NIEUW</span>':""}</b><small>${m[1]}</small></div></div><div class="admin-control-actions">${settingSwitch(`questionTypes.${k}.online`,s.online===true,"Online")} ${settingSwitch(`questionTypes.${k}.new`,s.new===true,"Nieuw-badge")}</div></div>`}).join("");
 const games=Object.entries(gameMeta).map(([k,m])=>{const s=SITE_CFG.gameTypes?.[k]||{};return `<div class="admin-control-card"><div class="admin-control-main"><div class="admin-control-icon">${k==="solo"?"👤":"🎮"}</div><div><b>${m[0]}</b><small>${m[1]}</small></div></div><div class="admin-control-actions">${settingSwitch(`gameTypes.${k}.online`,s.online===true,"Online")} ${settingSwitch(`gameTypes.${k}.new`,s.new===true,"Nieuw-badge")}</div></div>`}).join("");
 let quizPerm="";try{const all=(await get(ref(db,"quizzes"))).val()||{};const rows=[];Object.entries(all).forEach(([owner,qs])=>Object.entries(qs||{}).forEach(([id,q])=>{if(q&&typeof q==="object")rows.push({owner,id,q})}));rows.sort((a,b)=>(a.q.title||"").localeCompare(b.q.title||""));quizPerm=rows.map(x=>{const ok=quizAllowed(x.owner,x.id);return `<div class="admin-control-card"><div class="admin-control-main"><div class="admin-control-icon">🌍</div><div><b>${esc(x.q.title||"Naamloze quiz")}</b><small>${esc(x.q.creatorName||x.owner)} · ${arr(x.q.questions).length} onderdelen</small></div></div>${settingSwitch(`quizAccess.${x.owner}.${x.id}`,ok,"Online toegestaan")}</div>`}).join("")||`<div class="admin-empty">Nog geen quizzen gevonden.</div>`}catch(e){quizPerm=`<div class="admin-empty">Quizzen konden niet worden geladen.</div>`}
 c.innerHTML=`<div class="beheer-intro"><span class="eyebrow">BEHEER</span><h2>Alles wat spelers kunnen gebruiken</h2><p>Nieuwe onderdelen staan standaard offline. Zet ze hier bewust online.</p></div><div class="beheer-subtabs"><button class="beheer-subtab active" data-a="beheerSub" data-sub="avatars">👤 Poppetjes</button><button class="beheer-subtab" data-a="beheerSub" data-sub="questions">❓ Vraagtypes</button><button class="beheer-subtab" data-a="beheerSub" data-sub="games">🎮 Speltypes</button><button class="beheer-subtab" data-a="beheerSub" data-sub="quizzes">🌍 Quiztoestemming</button></div><div id="beheerSubPanel"></div>`;
 renderBeheerSub("avatars",{avatarCards,qtypes,games,quizPerm});
}
let beheerSub="avatars";
function renderBeheerSub(sub,cache){beheerSub=sub;document.querySelectorAll(".beheer-subtab").forEach(b=>b.classList.toggle("active",b.dataset.sub===sub));const c=$("#beheerSubPanel");if(!c)return;const title=sub==="avatars"?"Poppetjes":sub==="questions"?"Vraagtypes":sub==="games"?"Speltypes":"Toestemming per quiz";const intro=sub==="avatars"?"Bepaal per personage of het online is en of de Nieuw-badge zichtbaar is.":sub==="questions"?"Vraagtypes zijn standaard offline. Zet ze online wanneer spelers ze mogen gebruiken.":sub==="games"?"Speltypes zijn standaard offline. Zet ze online wanneer spelers ze mogen gebruiken.":"Blokkeer hier per quiz of die quiz online beschikbaar mag zijn.";let html="";if(sub==="avatars")html=cache?.avatarCards||"";else if(sub==="questions")html=cache?.qtypes||"";else if(sub==="games")html=cache?.games||"";else html=cache?.quizPerm||"";c.innerHTML=`<section class="admin-card"><div class="admin-card-head"><div><h3>${title}</h3><p>${intro}</p></div></div><div class="admin-control-list">${html}</div></section>`}

act.menu=()=>{const old=$("#menu");if(old)return old.remove();const m=document.createElement("div");m.id="menu";m.className="menu";m.innerHTML=`<button data-a="admin">⚙ Sitebeheer</button><button data-a="log">📢 Updatelog</button><hr><button data-a="out">Uitloggen</button>`;$(".hr")?.append(m)};
act.log=async()=>{act.closem();const m=document.createElement("div");m.className="modal";m.innerHTML=`<div class="card wide"><div class="mh"><h2>Updatelog</h2><div><button class="btn g sm" data-a="logNewUpdate" ${ADM?"":"style=\"display:none\""}>+ Nieuwe update</button> <button class="btn w sm" data-a="closem">Sluiten</button></div></div><div id="logc">Laden...</div></div>`;document.body.append(m);try{showLog(await loadUpdates())}catch(e){$("#logc").textContent="Kon de updates niet laden.";toast(em(e))}};
function showLog(l){if(l)LOGL=l;const c=$("#logc");if(!c)return;c.innerHTML=LOGL.length?LOGL.map(u=>`<div class="urow" data-a="uopen" data-id="${u.id}"><b>${esc(u.title)}</b><small>${fd(u.date)} · ${esc(u.time)}</small></div>`).join(""):"Nog geen updates."}
act.uopen=d=>{const u=UPD[d.id];if(!u)return;$("#logc").innerHTML=`<button class="btn w sm" data-a="ulist">← Terug</button><h2 style="margin-top:14px">${esc(u.title)}</h2><small>${fd(u.date)} · ${esc(u.time)}</small><p class="ubody">${esc(u.body)}</p>`};
act.ulist=()=>showLog();
act.logNewUpdate=async()=>{if(!ADM)return toast("Je hebt geen Sitebeheer-toegang.");tab="admin";home();adminTab="updates";renderAdminTabs();EDITU=null;updateEditorHtml()};
